type View = 'home' | 'report' | 'people' | 'safety' | 'emergency-lines'
type Coordinates = { latitude: number; longitude: number }

const isInAppBrowser = () => /Instagram|FBAN|FBAV|WhatsApp/i.test(navigator.userAgent)
const geolocationMessage = (error?: GeolocationPositionError) => {
  if (isInAppBrowser()) return 'El navegador interno de WhatsApp puede bloquear el GPS. Abre esta página en Safari o selecciona el punto manualmente en el mapa.'
  if (error?.code === 1) return 'El permiso de ubicación está bloqueado. Actívalo en los ajustes del navegador o selecciona el punto manualmente en el mapa.'
  if (error?.code === 3) return 'La ubicación tardó demasiado. Inténtalo otra vez o selecciona el punto manualmente en el mapa.'
  return 'No pudimos obtener tu ubicación. Puedes seleccionar el punto manualmente en el mapa.'
}
const requestCoordinates = (success: (coordinates: Coordinates) => void, failure: (message: string) => void) => {
  if (!navigator.geolocation) return failure('Este navegador no permite usar el GPS. Selecciona el punto manualmente en el mapa.')
  navigator.geolocation.getCurrentPosition(
    position => success({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
    error => failure(geolocationMessage(error)),
    { enableHighAccuracy: true, timeout: 12000, maximumAge: 60000 },
  )
}

const kindMeta: Record<ReportKind, { label: string; icon: typeof Siren; tone: string }> = {
  help: { label: 'Ayuda urgente', icon: Siren, tone: 'red' }, damage: { label: 'Daño estructural', icon: House, tone: 'orange' },
  landslide: { label: 'Deslizamiento', icon: AlertTriangle, tone: 'orange' }, road: { label: 'Vía bloqueada', icon: Navigation, tone: 'yellow' },
  water: { label: 'Agua disponible', icon: PackageOpen, tone: 'green' }, power: { label: 'Sin electricidad', icon: AlertTriangle, tone: 'yellow' },
  medical: { label: 'Punto médico', icon: HeartHandshake, tone: 'green' }, shelter: { label: 'Albergue', icon: House, tone: 'green' },
  aid: { label: 'Punto de ayuda', icon: PackageOpen, tone: 'green' },
}
const markerGlyph:Record<ReportKind,string>={help:'!',damage:'⌂',landslide:'▲',road:'━',water:'●',power:'⚡',medical:'✚',shelter:'⌂',aid:'◆'}
const locationMarkerIcon=divIcon({className:'leaflet-location-icon',html:'<span><i>●</i></span>',iconSize:[34,42],iconAnchor:[17,40],popupAnchor:[0,-38]})
const selectedMarkerIcon=divIcon({className:'leaflet-location-icon selected',html:'<span><i>✓</i></span>',iconSize:[34,42],iconAnchor:[17,40]})
const openIncidentDetail=(id:string)=>window.dispatchEvent(new CustomEvent('colombia-responde:incident',{detail:id}))

type IncidentGroup={latitude:number;longitude:number;items:Incident[]}
const groupNearbyIncidents=(items:Incident[],thresholdMetres=30):IncidentGroup[]=>{
  const groups:IncidentGroup[]=[]
  for(const item of items){
    const latitudeScale=111_320,longitudeScale=111_320*Math.cos(item.latitude*Math.PI/180)
    const group=groups.find(candidate=>Math.hypot((item.latitude-candidate.latitude)*latitudeScale,(item.longitude-candidate.longitude)*longitudeScale)<=thresholdMetres)
    if(group){
      group.items.push(item)
      group.latitude=group.items.reduce((sum,current)=>sum+current.latitude,0)/group.items.length
      group.longitude=group.items.reduce((sum,current)=>sum+current.longitude,0)/group.items.length
    }else groups.push({latitude:item.latitude,longitude:item.longitude,items:[item]})
  }
  return groups
}
const incidentIcon=(item:Incident,offset={x:0,y:0})=>{const meta=kindMeta[item.kind],tone=item.noAttend?'blue':meta.tone;return divIcon({className:'leaflet-report-icon',html:`<span class="leaflet-marker ${tone}"><i>${markerGlyph[item.kind]}</i></span>`,iconSize:[38,46],iconAnchor:[19-offset.x,44-offset.y],popupAnchor:[offset.x,offset.y-42]})}
function IncidentMarkers({items,onSelect}:{items:Incident[];onSelect:(id:string)=>void}){
  const areas=items.filter(item=>item.area&&item.area.length>=3).map(item=>{const meta=kindMeta[item.kind],color=item.noAttend?'#2563a6':meta.tone==='red'?'#d94b3f':meta.tone==='green'?'#26845c':'#e6813e';return <Polygon key={`area-${item.sourceId}`} positions={item.area!.map(point=>[point.latitude,point.longitude])} pathOptions={{color,fillColor:color,fillOpacity:.24,weight:3}} eventHandlers={{click:()=>onSelect(item.sourceId)}}><Popup><b>{item.noAttend?'NO ACUDIR':'Área aproximada · '+meta.label}</b><br/>{item.title}<br/><small>Toca para ver detalles y fotos</small></Popup></Polygon>})
  return <>{areas}{groupNearbyIncidents(items).flatMap(group=>group.items.map((item,index)=>{const meta=kindMeta[item.kind],angle=(Math.PI*2*index/group.items.length)-Math.PI/2,radius=group.items.length>1?Math.min(48,26+group.items.length*3):0,offset={x:Math.cos(angle)*radius,y:Math.sin(angle)*radius};return <Marker eventHandlers={{click:()=>onSelect(item.sourceId)}} key={item.sourceId} position={[group.latitude,group.longitude]} icon={incidentIcon(item,offset)} zIndexOffset={item.noAttend?1000+index:index}><Popup><b>{item.noAttend?'NO ACUDIR':item.needsPeople?'FALTAN PERSONAS':`${item.area?'Área aproximada · ':''}${meta.label}`}</b><br/>{item.title}<br/><small>{group.items.length>1?`${index+1} de ${group.items.length} reportes en este lugar · `:''}Toca para ver detalles y fotos</small></Popup></Marker>}))}</>
}

const blankLocation: ApiLocation = { departmentName: '', municipalityName: '', locality: '' }
const compressImage=async(file:File)=>{const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('No fue posible procesar la foto')),'image/webp',.8))}
const timeAgo = (date: string) => {const minutes=Math.max(1,Math.floor((Date.now()-new Date(date).getTime())/60000));if(minutes<60)return `hace ${minutes} min`;const hours=Math.floor(minutes/60),remainingMinutes=minutes%60;if(hours<24)return `hace ${hours} h${remainingMinutes?` ${remainingMinutes} min`:''}`;const days=Math.floor(hours/24),remainingHours=hours%24;return `hace ${days} día${days===1?'':'s'}${remainingHours?` y ${remainingHours} h`:''}`}
const mapIncident = (item: ApiIncident): Incident => {
  const [longitude, latitude] = item.coordinates.coordinates
  return { sourceId:item.id,id: item.id.slice(0, 8).toUpperCase(), kind: item.kind, title: item.title, description: item.description,
    place: `${item.location.municipalityName} · ${item.location.departmentName}`, time: timeAgo(item.createdAt),createdAt:item.createdAt,noAttend:item.sourceData?.saturation==='exceso',needsPeople:item.sourceData?.saturation==='faltan',
    verification: item.verificationStatus, people: item.peopleAtRisk, area:item.area,
    x: Math.min(90, Math.max(10, ((longitude + 79) / 13) * 80 + 10)), y: Math.min(90, Math.max(10, ((13 - latitude) / 17) * 80 + 10)), latitude, longitude }
}
function useIncidentPolling(onData:(items:Incident[])=>void,onStatus?:(online:boolean)=>void,onInitialDone?:()=>void){useEffect(()=>{let active=true,first=true;const refresh=async()=>{try{const data=await api.incidents();if(active){onData(data.map(mapIncident));onStatus?.(true)}}catch{if(active)onStatus?.(false)}finally{if(first){first=false;onInitialDone?.()}}};const visible=()=>{if(document.visibilityState==='visible')void refresh()};void refresh();const timer=window.setInterval(()=>void refresh(),15000);document.addEventListener('visibilitychange',visible);return()=>{active=false;window.clearInterval(timer);document.removeEventListener('visibilitychange',visible)}},[onData,onStatus,onInitialDone])}
function useIncidentStream(onIncident:(item:Incident)=>void,onStatus?:(online:boolean)=>void){useEffect(()=>{const stream=new EventSource(incidentStreamUrl);stream.onopen=()=>onStatus?.(true);stream.onmessage=event=>{try{const payload=JSON.parse(event.data) as {type?:string;incident?:ApiIncident};if(payload.type==='incident'&&payload.incident)onIncident(mapIncident(payload.incident))}catch{/* El sondeo periódico recuperará cualquier evento inválido. */}};return()=>stream.close()},[onIncident,onStatus])}
const mapPerson = (item: ApiMissingPerson): MissingPerson => ({ id: item.id, name: item.fullName, age: item.age,
  place: `${item.location.municipalityName} · ${item.location.departmentName}`, lastSeen: new Date(item.lastSeenAt).toLocaleString('es-CO'),
  status: item.status, initials: item.fullName.split(/\s+/).slice(0, 2).map(word => word[0]).join('').toUpperCase() })

function Header({ onHome, onEmergency, online }: { onHome: () => void; onEmergency: () => void; online: boolean }) {
  const [open, setOpen] = useState(false)
  return <header className="topbar"><button className="brand" onClick={onHome}><span className="brand-mark">CR</span><span>Colombia<br/><b>Responde</b></span></button>
    <div className={`network ${online ? '' : 'offline'}`}>{online ? <Wifi size={15}/> : <WifiOff size={15}/>} {online ? 'API conectada' : 'Sin conexión'}</div>
    <button className="icon-button" onClick={() => setOpen(!open)} aria-label="Abrir menú"><Menu/></button>
    {open && <div className="header-menu"><button onClick={() => { onHome(); setOpen(false) }}>Inicio</button><button onClick={() => { onEmergency(); setOpen(false) }}>Líneas de emergencia</button><a href="tel:123">Llamar al 123</a><button onClick={() => setOpen(false)}>Cerrar</button></div>}
  </header>
}

const tickerMessage=<><b>Información ciudadana:</b> Gracias por la colaboración. La mayoría de los puntos reportan insumos suficientes. Las necesidades que aún podrían presentarse son carpas y colchonetas; confirma directamente con cada punto antes de desplazarte o realizar una donación.</>
const childSafetyMessage=<><b>Protección de niñas y niños:</b> No permitas que una persona sin identificación clara se lleve a un menor. Verifica su parentesco o autorización con los responsables del punto y, ante cualquier duda, informa inmediatamente a las autoridades.</>
function TickerLine({message,className='',label}:{message:React.ReactNode;className?:string;label:string}){return <aside className={`info-ticker ${className}`} role="status" aria-label={label}><div className="info-ticker-track"><span>{message}</span><span aria-hidden="true">{message}</span></div></aside>}
function InfoTicker(){return <><TickerLine message={tickerMessage} label="Información ciudadana"/><TickerLine message={childSafetyMessage} label="Alerta de protección infantil" className="child-safety-ticker"/></>}

function EmergencyLinesPage({ close, coordinates }: { close: () => void; coordinates?: Coordinates }) {
  const suggested=coordinates?directoryForCoordinates(coordinates.latitude,coordinates.longitude):'national'
  const [region,setRegion]=useState(suggested)
  const directory=emergencyDirectories.find(item=>item.id===region)??emergencyDirectories[0]
  return <main className="form-page emergency-page"><button className="back" onClick={close}><ArrowLeft/> Volver</button><span className="section-kicker">DIRECTORIO TERRITORIAL</span><h1>Líneas de emergencia</h1><p>Los números pueden cambiar según la ciudad. Selecciona tu territorio y llama solamente si necesitas atención real.</p>
    <label>Territorio<select value={region} onChange={event=>setRegion(event.target.value)}>{emergencyDirectories.map(item=><option value={item.id} key={item.id}>{item.label} · {item.department}</option>)}</select></label>
    {directory.coverageNote&&<div className="coverage-note"><CircleHelp/>{directory.coverageNote}</div>}<div className="emergency-list">{directory.lines.map(line=><a className={line.primary?'primary-line':''} href={`tel:${line.number.replace(/\s/g,'')}`} key={`${directory.id}-${line.name}-${line.number}`}><span><b>{line.name}</b><small>{line.purpose}</small></span><strong>{line.number}</strong></a>)}</div>
    <div className="public-note emergency-source"><ShieldCheck/><div><b>Información territorial verificada</b><p>Revisada el {new Date(`${directory.verifiedAt}T12:00:00`).toLocaleDateString('es-CO')}. <a href={directory.sourceUrl} target="_blank" rel="noreferrer">Consultar fuente oficial</a>.</p></div></div>
  </main>
}

function Hero({ setView }: { setView: (v: View) => void }) {
  return <section className="hero"><div className="eyebrow"><span className="pulse"/> RED CIUDADANA DE EMERGENCIA</div><h1>Ayuda que encuentra<br/><em>a quien la necesita.</em></h1>
    <p>Reporta emergencias, encuentra personas y consulta recursos disponibles en todo Colombia.</p><div className="hero-actions">
      <button className="primary danger" onClick={() => setView('report')}><Siren/> Necesito ayuda</button>
      <button className="primary safe" onClick={() => setView('safety')}><CheckCircle2/> Estoy bien</button></div>
  </section>
}

function MapRecenter({ coordinates }: { coordinates?: Coordinates }) {
  const map = useMap()
  useEffect(() => { if (coordinates) map.flyTo([coordinates.latitude,coordinates.longitude],12,{duration:1.2}) }, [coordinates,map])
  return null
}

function MapPanel({ items, onLocate, onSelect=openIncidentDetail, userCoordinates }: { items: Incident[]; onLocate: () => void;onSelect?:(id:string)=>void; userCoordinates?: Coordinates }) {
  return <section className="map-card"><div className="map-head"><div><span className="section-kicker">SITUACIÓN ACTUAL</span><h2>Mapa ciudadano</h2></div><span className="region"><MapPin size={15}/> Colombia <ChevronDown size={14}/></span></div>
    <div className="map-canvas leaflet-map"><MapContainer center={[4.5709,-74.2973]} zoom={5} minZoom={4} scrollWheelZoom={false}>
      <TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>
      <MapRecenter coordinates={userCoordinates}/>{userCoordinates&&<Marker icon={locationMarkerIcon} position={[userCoordinates.latitude,userCoordinates.longitude]}><Popup><b>Tu ubicación aproximada</b></Popup></Marker>}
      <IncidentMarkers items={items} onSelect={onSelect}/>
    </MapContainer>{!items.length&&<div className="empty-map">No hay reportes para este filtro</div>}<button className="locate" onClick={onLocate} aria-label="Obtener ubicación"><Navigation size={18}/></button></div>
    <div className="legend"><span><i className="dot red"/> Urgente</span><span><i className="dot orange"/> Daño</span><span><i className="dot green"/> Recurso</span><span><i className="dot blue"/> No acudir</span></div></section>
}

function Feed({ items, loading, onAll, onSelect=openIncidentDetail }: { items: Incident[]; loading: boolean; onAll: () => void;onSelect?:(id:string)=>void }) {
  return <section className="feed"><div className="section-row"><div><span className="section-kicker">EN LA COMUNIDAD</span><h2>Reportes recientes</h2></div><button onClick={onAll}>Ver todos</button></div>
    {loading && <div className="loading"><LoaderCircle/> Cargando reportes…</div>}<div className="report-list">{items.map(item => { const meta=kindMeta[item.kind]; const Icon=meta.icon; return <article className="report" role="button" tabIndex={0} onClick={()=>onSelect(item.sourceId)} key={item.id}><div className={`report-icon ${item.noAttend?'blue':meta.tone}`}><Icon/></div><div className="report-body"><div className="report-title"><h3>{item.title}</h3><span>{item.id}</span></div>{item.noAttend&&<b className="no-attend-label">NO ACUDIR</b>}{item.needsPeople&&<b className="people-needed-label">FALTAN PERSONAS</b>}<p><MapPin size={14}/>{item.place}</p><div className="report-meta"><span><Clock3 size={13}/>{item.time}</span><span className={`verification ${item.verification}`}><ShieldCheck size={13}/>{item.verification==='verified'?'Verificado':item.verification==='official'?'Fuente oficial':item.verification==='community'?'Confirmación comunitaria':'Sin verificar'}</span></div></div></article>})}</div>
  </section>
}

function LocationPicker({ coordinates, onChange }: { coordinates?: Coordinates; onChange: (value: Coordinates) => void }) {
  function ClickHandler() { useMapEvents({ click: event => onChange({ latitude:event.latlng.lat, longitude:event.latlng.lng }) }); return null }
  return <div className="manual-map"><MapContainer center={coordinates ? [coordinates.latitude,coordinates.longitude] : [4.5709,-74.2973]} zoom={coordinates ? 15 : 5} scrollWheelZoom>
    <TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>
    <ClickHandler/>{coordinates&&<Marker icon={selectedMarkerIcon} position={[coordinates.latitude,coordinates.longitude]}/>} 
  </MapContainer><small>Toca el mapa para marcar la ubicación exacta.</small></div>
}

function LocationFields({ value, onChange, coordinates, setCoordinates }: { value: ApiLocation; onChange: (v: ApiLocation) => void; coordinates?: Coordinates; setCoordinates?: (v: Coordinates) => void }) {
  const [locationError,setLocationError]=useState(''),[manualMap,setManualMap]=useState(false)
  const locate = () => { setManualMap(false);setLocationError(''); requestCoordinates(value => setCoordinates?.(value), setLocationError) }
  const field = (key: keyof ApiLocation, placeholder: string, required=true) => <input required={required} value={value[key] || ''} placeholder={placeholder} onChange={e => onChange({ ...value, [key]:e.target.value })}/>
  return <div className="location-fields">{field('departmentName','Departamento')}{field('municipalityName','Municipio o distrito')}{field('locality','Barrio, vereda o localidad',false)}{setCoordinates&&<><div className="location-methods"><button type="button" className={!manualMap?'active':''} onClick={locate}><Navigation/> Usar mi ubicación actual</button><button type="button" className={manualMap?'active':''} onClick={()=>{setManualMap(true);setLocationError('')}}><MapPin/> Seleccionar otro punto</button></div>{coordinates&&<div className="selected-coordinates"><MapPin/> Punto seleccionado: {coordinates.latitude.toFixed(6)}, {coordinates.longitude.toFixed(6)}</div>}{locationError&&<div className="location-error" role="alert"><AlertTriangle/>{locationError}</div>}{manualMap&&<><div className="manual-map-help">Toca cualquier lugar del mapa para ubicar el reporte. No se utilizará el GPS del dispositivo.</div><LocationPicker coordinates={coordinates} onChange={value=>{setLocationError('');setCoordinates(value)}}/></>}</>}</div>
}

function SafetyPage({ close }: { close: () => void }) {
  const [mode,setMode]=useState<'create'|'search'>('create'),[fullName,setFullName]=useState(''),[location,setLocation]=useState<ApiLocation>(blankLocation),[message,setMessage]=useState(''),[coordinates,setCoordinates]=useState<Coordinates>(),[sending,setSending]=useState(false),[error,setError]=useState(''),[created,setCreated]=useState<ApiSafetyCheckIn>(),[query,setQuery]=useState(''),[results,setResults]=useState<ApiSafetyCheckIn[]>([])
  const submit=async(e:FormEvent)=>{e.preventDefault();setSending(true);setError('');try{const item=await api.createSafetyCheckIn({fullName,location,message:message||undefined,latitude:coordinates?.latitude,longitude:coordinates?.longitude});setCreated(item);if(item.deleteToken)localStorage.setItem(`safety-delete-${item.id}`,item.deleteToken)}catch(err){setError(err instanceof Error?err.message:'No fue posible confirmar tu estado')}finally{setSending(false)}}
  const search=async(e:FormEvent)=>{e.preventDefault();setSending(true);setError('');try{setResults(await api.safetyCheckIns(query))}catch(err){setError(err instanceof Error?err.message:'No fue posible buscar')}finally{setSending(false)}}
  const remove=async(item:ApiSafetyCheckIn)=>{const token=localStorage.getItem(`safety-delete-${item.id}`);if(!token)return;await api.removeSafetyCheckIn(item.id,token);localStorage.removeItem(`safety-delete-${item.id}`);setResults(current=>current.filter(result=>result.id!==item.id))}
  if(created)return <main className="form-page success-page"><CheckCircle2/><h1>{created.fullName} está bien</h1><p>Confirmación autodeclarada registrada. Tu familia puede encontrarte buscando tu nombre.</p><p>{created.location.municipalityName} · {created.location.departmentName}<br/>{new Date(created.createdAt).toLocaleString('es-CO')}</p><button className="primary safe full" onClick={()=>{setQuery(created.fullName);setMode('search');setCreated(undefined)}}>Consultar confirmación</button><button className="back" onClick={close}>Volver al inicio</button></main>
  return <main className="form-page safety-page"><button className="back" onClick={close}><ArrowLeft/> Volver</button><span className="section-kicker">CONFIRMACIÓN DE SEGURIDAD</span><h1>{mode==='create'?'Informar que estás bien':'Buscar confirmación'}</h1><div className="mode-tabs"><button className={mode==='create'?'active':''} onClick={()=>setMode('create')}>Estoy bien</button><button className={mode==='search'?'active':''} onClick={()=>setMode('search')}>Buscar a alguien</button></div>
    {mode==='create'?<form onSubmit={submit}><p>Publicaremos tu nombre, municipio, hora y mensaje. Las coordenadas exactas no se muestran.</p><label>Nombre completo<input required minLength={3} maxLength={180} value={fullName} onChange={e=>setFullName(e.target.value)}/></label><label>Ubicación aproximada<LocationFields value={location} onChange={setLocation} coordinates={coordinates} setCoordinates={setCoordinates}/></label><label>Mensaje opcional<textarea maxLength={500} rows={3} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Estoy con mi familia y en un lugar seguro."/></label><div className="privacy"><ShieldCheck/><p><b>Confirmación autodeclarada</b><br/>Caduca automáticamente en 30 días. Conservaremos en este dispositivo un token para eliminarla.</p></div>{error&&<p className="form-error">{error}</p>}<button disabled={sending} className="primary safe full">{sending?<><LoaderCircle/> Guardando…</>:'Confirmar que estoy bien'}</button></form>
    :<><form onSubmit={search}><div className="searchbox"><Search/><input required minLength={2} type="search" inputMode="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Nombre de la persona"/></div><button disabled={sending} className="primary safe full">{sending?'Buscando…':'Buscar confirmación'}</button></form>{error&&<p className="form-error">{error}</p>}<div className="safety-results">{results.map(item=><article className="safety-result" key={item.id}><CheckCircle2/><div><h3>{item.fullName} está bien</h3><p>{item.location.municipalityName} · {item.location.departmentName}</p><small>{new Date(item.createdAt).toLocaleString('es-CO')} · {item.status==='verified'?'Verificada':'Autodeclarada'}</small>{item.message&&<blockquote>{item.message}</blockquote>}</div>{localStorage.getItem(`safety-delete-${item.id}`)&&<button onClick={()=>void remove(item)}>Eliminar mi confirmación</button>}</article>)}</div>{!sending&&results.length===0&&query&&<p className="empty-state">No encontramos una confirmación activa con ese nombre.</p>}</>}
  </main>
}

function IncidentDetailPage({id,close}:{id:string;close:()=>void}){const[data,setData]=useState<ApiIncidentDetail>(),[error,setError]=useState('');useEffect(()=>{api.incident(id).then(setData).catch(reason=>setError(reason instanceof Error?reason.message:'No fue posible cargar el reporte'))},[id]);if(error)return <main className="form-page"><button className="back" onClick={close}><ArrowLeft/> Volver</button><p className="form-error">{error}</p></main>;if(!data)return <main className="form-page"><div className="loading"><LoaderCircle/> Cargando detalle…</div></main>;const meta=kindMeta[data.kind],externalMedia=data.sourceData?.media?.filter(item=>item.url&&item.mime?.startsWith('image/'))||[];return <main className="form-page incident-detail"><button className="back" onClick={close}><ArrowLeft/> Volver al mapa</button><span className="section-kicker">{meta.label.toUpperCase()}</span><h1>{data.title}</h1><p><MapPin size={15}/>{data.location.locality?`${data.location.locality} · `:''}{data.location.municipalityName} · {data.location.departmentName}</p><div className="verification"><ShieldCheck size={14}/> {data.verificationStatus==='unverified'?'Reporte ciudadano sin verificar':'Evidencia adjunta'}</div>{data.sourceData?.saturation==='exceso'&&<div className="operational-status no-attend"><b>NO ACUDIR</b><span>Este punto informa que no necesita más personas en este momento.</span></div>}{data.sourceData?.saturation==='faltan'&&<div className="operational-status people-needed"><b>FALTAN PERSONAS</b><span>Este punto continúa solicitando apoyo presencial.</span></div>}{data.sourceName&&<div className="external-source"><CircleHelp/><div><b>Información importada</b><p>Fuente: <a href={data.sourceUrl} target="_blank" rel="noreferrer">{data.sourceName}</a>.<br/><b>Registrado originalmente:</b> {new Date(data.createdAt).toLocaleString('es-CO')}.<br/><b>Última actualización en el origen:</b> {data.sourceUpdatedAt?new Date(data.sourceUpdatedAt).toLocaleString('es-CO'):'sin fecha'}. Confirma su vigencia antes de actuar.</p></div></div>}<p className="detail-description">{data.description}</p>{data.peopleAtRisk!==undefined&&<p><b>Personas en riesgo:</b> {data.peopleAtRisk}</p>}{Boolean(data.sourceData?.needs?.length)&&<section className="source-needs"><h2>Qué hace falta</h2><div>{data.sourceData!.needs!.map((need,index)=><span key={`${need}-${index}`}>{need}</span>)}</div></section>}{Boolean(data.sourceLog?.length)&&<section className="source-log"><h2>Bitácora del punto</h2>{data.sourceLog!.map((entry,index)=><article key={`${entry.timestamp}-${index}`}><time>{new Date(entry.timestamp).toLocaleString('es-CO')}</time><p>{entry.text}{entry.author&&<small> — {entry.author}</small>}</p></article>)}</section>}<h2>Fotografías</h2>{data.evidence.length||externalMedia.length?<div className="evidence-gallery">{data.evidence.map(photo=><a href={photo.url} target="_blank" rel="noreferrer" key={photo.id}><img src={photo.url} alt={`Evidencia de ${data.title}`} loading="lazy"/></a>)}{externalMedia.map((photo,index)=><a href={photo.url} target="_blank" rel="noreferrer" key={`external-${index}`}><img src={photo.url} alt={photo.caption||`Evidencia externa de ${data.title}`} loading="lazy"/></a>)}</div>:<div className="no-evidence"><Camera/> Este reporte no tiene fotografías.</div>}<div className="privacy"><ShieldCheck/><p>Las fotografías son evidencia ciudadana y no implican verificación oficial.</p></div></main>}

function CitizenActionsSection({onSelect}:{onSelect:(id:string)=>void}){const[items,setItems]=useState<CitizenAction[]>([]);useEffect(()=>{api.citizenActions().then(setItems).catch(()=>setItems([]))},[]);if(!items.length)return null;return <section className="citizen-actions"><div className="section-row"><div><span className="section-kicker">INICIATIVAS VERIFICADAS POR SU RESPONSABLE</span><h2>Acciones ciudadanas</h2></div></div><div className="citizen-action-list">{items.map(item=><article className="citizen-action-card" role="button" tabIndex={0} onClick={()=>onSelect(item.id)} onKeyDown={event=>{if(event.key==='Enter')onSelect(item.id)}} key={item.id}><HeartHandshake/><div><h3>{item.title}</h3><p>{item.actionDescription}</p><small><MapPin/> {item.locality?`${item.locality} · `:''}{item.municipalityName}</small></div><span>Ver detalle</span></article>)}</div></section>}

function CitizenActionDetailPage({id,close}:{id:string;close:()=>void}){const[data,setData]=useState<CitizenAction>(),[error,setError]=useState('');useEffect(()=>{api.citizenAction(id).then(setData).catch(reason=>setError(reason instanceof Error?reason.message:'No fue posible cargar la acción'))},[id]);if(error)return <main className="form-page"><button className="back" onClick={close}><ArrowLeft/> Volver</button><p className="form-error">{error}</p></main>;if(!data)return <main className="form-page"><div className="loading"><LoaderCircle/> Cargando acción…</div></main>;return <main className="form-page citizen-action-detail"><button className="back" onClick={close}><ArrowLeft/> Volver</button><span className="section-kicker">ACCIÓN CIUDADANA ACEPTADA POR SU RESPONSABLE</span><h1>{data.title}</h1><p><MapPin/> {data.locality?`${data.locality} · `:''}{data.municipalityName} · {data.departmentName}</p><section><h2>Acción que se realizará</h2><p>{data.actionDescription}</p></section><section><h2>Persona responsable</h2><dl><dt>Nombre</dt><dd>{data.contactName}</dd><dt>Teléfono</dt><dd><a href={`tel:${data.contactPhone.replace(/[^+\d]/g,'')}`}>{data.contactPhone}</a></dd></dl></section>{data.donationMethod&&<section><h2>Método de donación</h2><p className="donation-details">{data.donationMethod}</p></section>}<div className="donation-warning"><ShieldCheck/><p><b>Verifica antes de donar</b><br/>Comunícate directamente con la persona responsable y corrobora su identidad, la acción y los datos de pago antes de enviar dinero o insumos. La aceptación autoriza la publicación, pero no constituye verificación financiera ni respaldo oficial de Colombia Responde.</p></div></main>}

function CitizenActionValidationPage(){const token=new URLSearchParams(location.search).get('token')||'',[data,setData]=useState<CitizenAction>(),[error,setError]=useState(''),[accepted,setAccepted]=useState(false),[sending,setSending]=useState(false),[result,setResult]=useState<'accepted'|'declined'>();useEffect(()=>{if(!token){setError('El enlace no contiene un token de validación');return}api.citizenActionValidation(token).then(setData).catch(reason=>setError(reason instanceof Error?reason.message:'No fue posible abrir el enlace'))},[token]);const decide=async(decision:'accept'|'decline')=>{setSending(true);setError('');try{await api.validateCitizenAction(token,decision);setResult(decision==='accept'?'accepted':'declined')}catch(reason){setError(reason instanceof Error?reason.message:'No fue posible registrar tu decisión')}finally{setSending(false)}};if(result)return <main className="consent-page"><ShieldCheck/><h1>{result==='accepted'?'Publicación autorizada':'Publicación rechazada'}</h1><p>{result==='accepted'?'La acción ciudadana ya puede mostrarse públicamente con los datos que revisaste.':'Los datos de esta solicitud fueron eliminados y no serán publicados.'}</p></main>;if(error)return <main className="consent-page"><AlertTriangle/><h1>No pudimos validar el enlace</h1><p>{error}</p></main>;if(!data)return <main className="consent-page"><LoaderCircle/><p>Cargando información para revisión…</p></main>;return <main className="consent-page"><div className="brand-mark">CR</div><span className="section-kicker">CONSENTIMIENTO DE PUBLICACIÓN</span><h1>Revisa tus datos antes de autorizar</h1><p>Nada de esto es público todavía. Verifica exactamente la información que aparecerá en Colombia Responde.</p><div className="consent-review"><h2>{data.title}</h2><dl><dt>Nombre público</dt><dd>{data.contactName}</dd><dt>Teléfono público</dt><dd>{data.contactPhone}</dd><dt>Ubicación</dt><dd>{data.locality?`${data.locality}, `:''}{data.municipalityName}, {data.departmentName}</dd><dt>Acción</dt><dd>{data.actionDescription}</dd><dt>Método de donación</dt><dd>{data.donationMethod||'No se publicará un método de donación.'}</dd></dl></div><label className="consent-check"><input type="checkbox" checked={accepted} onChange={event=>setAccepted(event.target.checked)}/> Confirmo que los datos son correctos, soy la persona responsable o estoy autorizada para aprobarlos, y acepto su publicación.</label>{error&&<p className="form-error">{error}</p>}<div className="consent-actions"><button disabled={sending} className="outline" onClick={()=>void decide('decline')}>Rechazar y eliminar</button><button disabled={sending||!accepted} className="primary safe" onClick={()=>void decide('accept')}>Aceptar y publicar</button></div><small>Este enlace vence el {new Date(data.validationExpiresAt).toLocaleString('es-CO')} y solo puede utilizarse una vez.</small></main>}

function ReportForm({ close, onCreated, initialCoordinates }: { close: () => void; onCreated: (i: ApiIncident) => void; initialCoordinates?: Coordinates }) {
  const [kind,setKind]=useState<ReportKind>('help'), [location,setLocation]=useState<ApiLocation>(blankLocation), [coordinates,setCoordinates]=useState<Coordinates|undefined>(initialCoordinates)
  const [title,setTitle]=useState(''), [description,setDescription]=useState(''), [peopleAtRisk,setPeopleAtRisk]=useState(''),[photos,setPhotos]=useState<File[]>([]), [sending,setSending]=useState(false), [error,setError]=useState(''), [sent,setSent]=useState<ApiIncident>()
  const submit=async(e:FormEvent)=>{e.preventDefault();if(!coordinates){setError('Usa tu ubicación actual o selecciona el punto en el mapa antes de enviar.');return}setSending(true);setError('');try{const created=await api.createIncident({kind,title,description,location,latitude:coordinates.latitude,longitude:coordinates.longitude,peopleAtRisk:peopleAtRisk?Number(peopleAtRisk):undefined});for(const photo of photos){const compressed=await compressImage(photo);if(compressed.size>3145728)throw new Error('Una fotografía supera 3 MB después de comprimir');const upload=await api.evidenceUploadUrl(created.id,compressed);const response=await fetch(upload.uploadUrl,{method:'PUT',headers:{'Content-Type':compressed.type},body:compressed});if(!response.ok)throw new Error('No fue posible subir una fotografía');await api.completeEvidence(created.id,upload.id)}setSent(created);onCreated(created)}catch(err){setError(err instanceof Error?err.message:'No fue posible enviar el reporte')}finally{setSending(false)}}
  if(sent)return <main className="form-page success-page"><CheckCircle2/><h1>Reporte registrado</h1><p>La API confirmó el reporte. Su estado inicial es “sin verificar”.</p><b>#{sent.id.slice(0,8).toUpperCase()}</b><button className="primary safe" onClick={close}>Volver al mapa</button></main>
  return <main className="form-page"><button className="back" onClick={close}><ArrowLeft/> Volver</button><span className="section-kicker">NUEVO REPORTE</span><h1>¿Qué está ocurriendo?</h1><p>Si existe peligro inmediato, aléjate de la zona y contacta al 123.</p><form onSubmit={submit}>
    <div className="kind-grid">{(Object.entries(kindMeta) as [ReportKind,typeof kindMeta[ReportKind]][]).map(([key,meta])=>{const Icon=meta.icon;return <button type="button" className={kind===key?'selected':''} onClick={()=>setKind(key)} key={key}><Icon/><span>{meta.label}</span></button>})}</div>
    <label>Título<input required minLength={3} maxLength={160} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ej. Vivienda afectada"/></label><label>Ubicación territorial<LocationFields value={location} onChange={setLocation} coordinates={coordinates} setCoordinates={setCoordinates}/></label>
    <label>Personas en riesgo<input min={0} max={10000} type="number" value={peopleAtRisk} onChange={e=>setPeopleAtRisk(e.target.value)} placeholder="Opcional"/></label><label>Cuéntanos lo esencial<textarea required minLength={5} maxLength={2000} value={description} onChange={e=>setDescription(e.target.value)} rows={4}/></label><label className="photo-picker"><Camera/> Añadir fotografías (máximo 3)<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple onChange={e=>{const chosen=Array.from(e.target.files??[]).slice(0,3);setPhotos(chosen)}}/></label>{photos.length>0&&<div className="photo-selection">{photos.map(file=><span key={`${file.name}-${file.size}`}>{file.name}</span>)}</div>}
    <div className="privacy"><ShieldCheck/><p><b>Publica con cuidado</b><br/>No incluyas teléfonos, documentos ni información médica.</p></div>{error&&<p className="form-error">{error}</p>}<button disabled={sending} className="primary danger full">{sending?<><LoaderCircle/> Enviando…</>:'Enviar reporte'}</button></form></main>
}

function PeoplePage({ close }: { close: () => void }) {
  const [query,setQuery]=useState(''), [people,setPeople]=useState<MissingPerson[]>([]), [loading,setLoading]=useState(true), [creating,setCreating]=useState(false), [error,setError]=useState('')
  const [fullName,setFullName]=useState(''), [age,setAge]=useState(''), [lastSeenAt,setLastSeenAt]=useState(''), [details,setDetails]=useState(''), [location,setLocation]=useState<ApiLocation>(blankLocation)
  const load=useCallback(async()=>{setLoading(true);try{setPeople((await api.people(query)).map(mapPerson));setError('')}catch(err){setError(err instanceof Error?err.message:'Error de conexión')}finally{setLoading(false)}},[query])
  useEffect(()=>{const timer=setTimeout(()=>void load(),300);return()=>clearTimeout(timer)},[load])
  const submit=async(e:FormEvent)=>{e.preventDefault();setLoading(true);try{await api.createPerson({fullName,age:age?Number(age):undefined,location,lastSeenAt:new Date(lastSeenAt).toISOString(),lastSeenDetails:details,contactToken:crypto.randomUUID()});setCreating(false);setFullName('');setAge('');setDetails('');await load()}catch(err){setError(err instanceof Error?err.message:'No fue posible registrar a la persona');setLoading(false)}}
  return <main className="form-page people-page"><button className="back" onClick={close}><ArrowLeft/> Volver</button><span className="section-kicker">REUNIFICACIÓN FAMILIAR</span><h1>{creating?'Reportar una persona':'Buscar una persona'}</h1>
    {!creating?<><p>Consulta la base ciudadana por nombre.</p><div className="searchbox"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Nombre de la persona"/>{query&&<button onClick={()=>setQuery('')}><X/></button>}</div><button className="outline full" onClick={()=>setCreating(true)}><UserRoundSearch/> Reportar persona desaparecida</button>{loading&&<div className="loading"><LoaderCircle/> Buscando…</div>}{error&&<p className="form-error">{error}</p>}<div className="people-list">{people.map(person=><article className="person" key={person.id}><div className="avatar">{person.initials}</div><div><h3>{person.name}{person.age!==undefined?`, ${person.age}`:''}</h3><p><MapPin size={13}/>{person.place}</p><small>{person.lastSeen}</small></div><span className={`person-status ${person.status}`}>{person.status==='missing'?'Desaparecida':person.status==='sighting'?'Avistamiento':'Localizada'}</span></article>)}</div>{!loading&&!people.length&&<p className="empty-state">No se encontraron personas con ese nombre.</p>}</>
    :<form onSubmit={submit}><label>Nombre completo<input required minLength={3} value={fullName} onChange={e=>setFullName(e.target.value)}/></label><label>Edad aproximada<input type="number" min={0} max={125} value={age} onChange={e=>setAge(e.target.value)}/></label><label>Último contacto<input required type="datetime-local" value={lastSeenAt} onChange={e=>setLastSeenAt(e.target.value)}/></label><label>Ubicación territorial<LocationFields value={location} onChange={setLocation}/></label><label>Detalles<textarea required minLength={5} maxLength={2000} value={details} onChange={e=>setDetails(e.target.value)} rows={4}/></label>{error&&<p className="form-error">{error}</p>}<div className="form-actions"><button type="button" className="outline" onClick={()=>setCreating(false)}>Cancelar</button><button disabled={loading} className="primary danger">Registrar</button></div></form>}
  </main>
}

function CitizenActionAdminForm({token,close}:{token:string;close:()=>void}){const[title,setTitle]=useState(''),[contactName,setContactName]=useState(''),[contactPhone,setContactPhone]=useState(''),[actionDescription,setActionDescription]=useState(''),[donationMethod,setDonationMethod]=useState(''),[departmentName,setDepartmentName]=useState('Valle del Cauca'),[municipalityName,setMunicipalityName]=useState('Santiago de Cali'),[locality,setLocality]=useState(''),[sending,setSending]=useState(false),[error,setError]=useState(''),[validationUrl,setValidationUrl]=useState('');const submit=async(event:FormEvent)=>{event.preventDefault();setSending(true);setError('');try{const result=await api.adminCreateCitizenAction(token,{title,contactName,contactPhone,actionDescription,donationMethod:donationMethod||undefined,departmentName,municipalityName,locality:locality||undefined});setValidationUrl(result.validationUrl)}catch(reason){setError(reason instanceof Error?reason.message:'No fue posible crear la acción')}finally{setSending(false)}};if(validationUrl)return <div className="action-link-result"><ShieldCheck/><h2>Enlace privado generado</h2><p>Envía este enlace únicamente a la persona responsable. La acción no será pública hasta que revise y acepte los datos.</p><textarea readOnly rows={4} value={validationUrl}/><button className="primary safe full" onClick={()=>void navigator.clipboard.writeText(validationUrl)}>Copiar enlace</button><button className="outline full" onClick={close}>Crear otra alerta</button></div>;return <form onSubmit={submit}><button type="button" className="back" onClick={close}><ArrowLeft/> Volver a alertas</button><h2>Nueva acción ciudadana</h2><div className="consent-admin-note"><ShieldCheck/>Se creará como borrador privado. La persona responsable deberá aceptar la publicación desde un enlace único que vence en 72 horas.</div><label>Título<input required minLength={3} maxLength={160} value={title} onChange={event=>setTitle(event.target.value)} placeholder="Ej. Recolección comunitaria de alimentos"/></label><div className="admin-row"><label>Nombre responsable<input required minLength={3} value={contactName} onChange={event=>setContactName(event.target.value)}/></label><label>Teléfono<input required minLength={7} value={contactPhone} onChange={event=>setContactPhone(event.target.value)} inputMode="tel"/></label></div><label>Acción que se realizará<textarea required minLength={10} rows={5} value={actionDescription} onChange={event=>setActionDescription(event.target.value)}/></label><label>Método de donación o datos de pago<textarea rows={4} value={donationMethod} onChange={event=>setDonationMethod(event.target.value)} placeholder="Opcional: llave, banco, tipo de cuenta y titular"/></label><div className="admin-row"><label>Departamento<input required value={departmentName} onChange={event=>setDepartmentName(event.target.value)}/></label><label>Municipio<input required value={municipalityName} onChange={event=>setMunicipalityName(event.target.value)}/></label></div><label>Barrio o referencia<input value={locality} onChange={event=>setLocality(event.target.value)}/></label>{error&&<p className="form-error">{error}</p>}<button disabled={sending} className="primary safe full">{sending?'Creando enlace…':'Crear enlace de validación'}</button></form>}

function AdminMap({point,area,areaMode,items,onPoint,onAreaPoint,onSelect}:{point?:Coordinates;area:AreaPoint[];areaMode:boolean;items:Incident[];onPoint:(value:Coordinates)=>void;onAreaPoint:(value:AreaPoint)=>void;onSelect:(id:string)=>void}){
  function Click(){useMapEvents({click:event=>{const value={latitude:event.latlng.lat,longitude:event.latlng.lng};if(areaMode)onAreaPoint(value);else onPoint(value)}});return null}
  const positions=area.map(value=>[value.latitude,value.longitude] as [number,number])
  return <MapContainer className="admin-map" center={[4.5709,-74.2973]} zoom={6} scrollWheelZoom><TileLayer attribution='&copy; OpenStreetMap contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/><Click/><IncidentMarkers items={items} onSelect={onSelect}/>{!areaMode&&point&&<Marker icon={selectedMarkerIcon} position={[point.latitude,point.longitude]}><Popup>Nuevo punto seleccionado</Popup></Marker>}{areaMode&&positions.length>1&&<Polyline positions={positions} pathOptions={{color:'#d94b3f',weight:3,dashArray:'7 7'}}/>}{areaMode&&positions.length>=3&&<Polygon positions={positions} pathOptions={{color:'#d94b3f',fillColor:'#d94b3f',fillOpacity:.22,weight:3}}/>}{areaMode&&positions.map((position,index)=><Marker key={`${position[0]}-${position[1]}-${index}`} icon={selectedMarkerIcon} position={position}><Popup>Vértice {index+1}</Popup></Marker>)}</MapContainer>
}

function AdminPage(){
  const[token]=useState(()=>{const params=new URLSearchParams(location.search),incoming=params.get('token');if(incoming){sessionStorage.setItem('cr-admin-token',incoming);history.replaceState({},'',location.pathname)}return incoming||sessionStorage.getItem('cr-admin-token')||''})
  const[point,setPoint]=useState<Coordinates>(),[area,setArea]=useState<AreaPoint[]>([]),[areaMode,setAreaMode]=useState(false),[kind,setKind]=useState<ReportKind>('help'),[title,setTitle]=useState(''),[description,setDescription]=useState(''),[department,setDepartment]=useState(''),[municipality,setMunicipality]=useState(''),[locality,setLocality]=useState(''),[people,setPeople]=useState(''),[photos,setPhotos]=useState<File[]>([]),[sending,setSending]=useState(false),[message,setMessage]=useState(''),[items,setItems]=useState<Incident[]>([]),[selected,setSelected]=useState<string>(),[creatingAction,setCreatingAction]=useState(false)
  useIncidentPolling(setItems)
  const mergeIncident=useCallback((incoming:Incident)=>setItems(current=>[incoming,...current.filter(item=>item.sourceId!==incoming.sourceId)]),[])
  useIncidentStream(mergeIncident)
  const selectMode=(isArea:boolean)=>{setAreaMode(isArea);setMessage('');if(isArea)setPoint(undefined);else setArea([])}
  const submit=async(e:FormEvent)=>{e.preventDefault();if(areaMode&&area.length<3)return setMessage('Marca al menos 3 vértices para definir el área');if(!areaMode&&!point)return setMessage('Selecciona un punto en el mapa');const center=areaMode?{latitude:area.reduce((sum,value)=>sum+value.latitude,0)/area.length,longitude:area.reduce((sum,value)=>sum+value.longitude,0)/area.length}:point!;setSending(true);setMessage('');try{const created=await api.adminCreateIncident(token,{kind,title,description,location:{departmentName:department,municipalityName:municipality,locality:locality||undefined},latitude:center.latitude,longitude:center.longitude,peopleAtRisk:people?Number(people):undefined,area:areaMode?area:undefined});for(const photo of photos){const blob=await compressImage(photo),upload=await api.evidenceUploadUrl(created.id,blob);const response=await fetch(upload.uploadUrl,{method:'PUT',headers:{'Content-Type':blob.type},body:blob});if(!response.ok)throw new Error('Falló la carga de una fotografía');await api.completeEvidence(created.id,upload.id)}mergeIncident(mapIncident(created));setMessage(`Reporte ${created.id.slice(0,8).toUpperCase()} registrado`);setTitle('');setDescription('');setPhotos([]);setPoint(undefined);setArea([])}catch(error){setMessage(error instanceof Error?error.message:'No fue posible registrar la alerta')}finally{setSending(false)}}
  if(!token)return <main className="admin-login"><h1>Acceso administrativo</h1><p>Abre el enlace con un token válido.</p></main>
  return <main className="admin-shell"><header><div className="brand-mark">CR</div><div><b>Colombia Responde</b><span>Panel administrativo</span></div><a href="/">Ver sitio público</a></header><div className="admin-workspace"><section className="admin-map-panel"><div><h1>Mapa de alertas</h1><p>{items.length} reportes registrados · actualización en tiempo real. {areaMode?`Haz clic para marcar el contorno (${area.length} vértices).`:'Haz clic para seleccionar el punto.'}</p><div className="geometry-toolbar"><button className={!areaMode?'active':''} onClick={()=>selectMode(false)}>Punto exacto</button><button className={areaMode?'active':''} onClick={()=>selectMode(true)}>Área aproximada</button>{areaMode&&<><button disabled={!area.length} onClick={()=>setArea(current=>current.slice(0,-1))}>Deshacer vértice</button><button disabled={!area.length} onClick={()=>setArea([])}>Limpiar área</button></>}</div></div><AdminMap point={point} area={area} areaMode={areaMode} items={items} onPoint={setPoint} onAreaPoint={value=>setArea(current=>[...current,value])} onSelect={setSelected}/></section><aside>{selected?<IncidentDetailPage id={selected} close={()=>setSelected(undefined)}/>:creatingAction?<CitizenActionAdminForm token={token} close={()=>setCreatingAction(false)}/>:<form onSubmit={submit}><button type="button" className="create-citizen-action" onClick={()=>setCreatingAction(true)}><HeartHandshake/> Crear acción ciudadana</button><h2>Nueva alerta {areaMode?'por área':'por punto'}</h2>{areaMode&&<div className="area-help"><MapPin/>Marca al menos tres puntos alrededor de la zona. El último se conectará automáticamente con el primero.</div>}<label>Situación<select value={kind} onChange={e=>setKind(e.target.value as ReportKind)}>{Object.entries(kindMeta).map(([key,value])=><option value={key} key={key}>{value.label}</option>)}</select></label><label>Título<input required minLength={3} value={title} onChange={e=>setTitle(e.target.value)}/></label><div className="admin-row"><label>Departamento<input required value={department} onChange={e=>setDepartment(e.target.value)}/></label><label>Municipio<input required value={municipality} onChange={e=>setMunicipality(e.target.value)}/></label></div><label>Barrio o referencia<input value={locality} onChange={e=>setLocality(e.target.value)}/></label><label>Personas en riesgo<input type="number" min="0" value={people} onChange={e=>setPeople(e.target.value)}/></label><label>Descripción<textarea required minLength={5} rows={5} value={description} onChange={e=>setDescription(e.target.value)}/></label><label className="photo-picker"><Camera/> Añadir hasta 3 fotos<input type="file" multiple accept="image/jpeg,image/png,image/webp" onChange={e=>setPhotos(Array.from(e.target.files??[]).slice(0,3))}/></label>{message&&<p className={message.startsWith('Reporte')?'admin-success':'form-error'}>{message}</p>}<button className="primary danger full" disabled={sending}>{sending?'Publicando…':areaMode?'Publicar área':'Publicar alerta'}</button></form>}</aside></div></main>
}

function PublicApp(){const[view,setView]=useState<View>('home'),[filter,setFilter]=useState<'all'|'urgent'|'resources'>('all'),[timeFilter,setTimeFilter]=useState<'1'|'5'|'10'|'all'>('all'),[incidents,setIncidents]=useState<Incident[]>([]),[loading,setLoading]=useState(true),[online,setOnline]=useState(false),[coordinates,setCoordinates]=useState<Coordinates>(),[locationError,setLocationError]=useState(''),[selectedIncident,setSelectedIncident]=useState<string>(),[selectedAction,setSelectedAction]=useState<string>()
  useIncidentPolling(setIncidents,setOnline,useCallback(()=>setLoading(false),[]));const mergeIncident=useCallback((incoming:Incident)=>setIncidents(current=>[incoming,...current.filter(item=>item.sourceId!==incoming.sourceId)]),[]);useIncidentStream(mergeIncident,setOnline);const visible=useMemo(()=>{const maximumAge=timeFilter==='all'?Infinity:Number(timeFilter)*60*60*1000,now=Date.now();return incidents.filter(i=>(filter==='all'||(filter==='urgent'?['help','damage','landslide'].includes(i.kind):['water','medical','shelter','aid'].includes(i.kind)))&&now-new Date(i.createdAt).getTime()<=maximumAge).sort((a,b)=>new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime())},[filter,timeFilter,incidents])
  useEffect(()=>{const handler=(event:Event)=>setSelectedIncident((event as CustomEvent<string>).detail);window.addEventListener('colombia-responde:incident',handler);return()=>window.removeEventListener('colombia-responde:incident',handler)},[])
  const locate=()=>{setLocationError('');requestCoordinates(value=>{setCoordinates(value);setView('report')},setLocationError)}
  const locateOnMap=()=>{setLocationError('');requestCoordinates(setCoordinates,setLocationError)}
  const created=(item:ApiIncident)=>{setIncidents(current=>[mapIncident(item),...current]);setOnline(true)}
  const header=<><Header onHome={()=>setView('home')} onEmergency={()=>setView('emergency-lines')} online={online}/><InfoTicker/></>
  if(selectedIncident)return <div className="app">{header}<IncidentDetailPage id={selectedIncident} close={()=>setSelectedIncident(undefined)}/></div>
  if(selectedAction)return <div className="app">{header}<CitizenActionDetailPage id={selectedAction} close={()=>setSelectedAction(undefined)}/></div>
  if(view==='safety')return <div className="app">{header}<SafetyPage close={()=>setView('home')}/><footer><div className="brand-mark">CR</div><p>Colombia Responde<br/><small>Tecnología abierta para ayudarnos.</small></p></footer></div>
  if(view==='emergency-lines')return <div className="app">{header}<EmergencyLinesPage close={()=>setView('home')} coordinates={coordinates}/><footer><div className="brand-mark">CR</div><p>Colombia Responde<br/><small>Tecnología abierta para ayudarnos.</small></p></footer></div>
  return <div className="app">{header}{view==='report'?<ReportForm close={()=>setView('home')} onCreated={created} initialCoordinates={coordinates}/>:view==='people'?<PeoplePage close={()=>setView('home')}/>:<><Hero setView={setView}/><button className="location global-location" onClick={locate}><MapPin size={17}/> Usar mi ubicación para reportar <span>›</span></button>{locationError&&<div className="location-error home-location-error" role="alert"><AlertTriangle/><span>{locationError}<button onClick={()=>setView('report')}>Seleccionar en el mapa</button></span></div>}<nav className="quick-actions"><button onClick={()=>setView('people')}><UserRoundSearch/><span><b>Buscar persona</b><small>Desaparecidos y localizados</small></span></button><button onClick={()=>setView('report')}><House/><span><b>Reportar daño</b><small>Viviendas, vías y servicios</small></span></button></nav><div className="filterbar"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>Todos</button><button className={filter==='urgent'?'active':''} onClick={()=>setFilter('urgent')}>Urgentes</button><button className={filter==='resources'?'active':''} onClick={()=>setFilter('resources')}>Ayuda disponible</button></div><div className="time-filterbar" aria-label="Filtrar reportes por antigüedad"><b><Clock3/> Antigüedad</b><div><button className={timeFilter==='1'?'active':''} onClick={()=>setTimeFilter('1')}>1 hora</button><button className={timeFilter==='5'?'active':''} onClick={()=>setTimeFilter('5')}>5 horas</button><button className={timeFilter==='10'?'active':''} onClick={()=>setTimeFilter('10')}>10 horas</button><button className={timeFilter==='all'?'active':''} onClick={()=>setTimeFilter('all')}>Todos</button></div></div><MapPanel items={visible} onLocate={locateOnMap} userCoordinates={coordinates}/><Feed items={visible} loading={loading} onAll={()=>{setFilter('all');setTimeFilter('all')}}/><CitizenActionsSection onSelect={setSelectedAction}/><section className="public-note"><CircleHelp/><div><b>Plataforma ciudadana, no oficial</b><p>La información debe contrastarse con autoridades. <button className="text-link" onClick={()=>setView('emergency-lines')}>Consulta las líneas de tu región</button>.</p></div></section></>}<footer><div className="brand-mark">CR</div><p>Colombia Responde<br/><small>Tecnología abierta para ayudarnos.</small></p><span><Users size={15}/> Hecho en comunidad</span></footer></div>}

export default function App(){return location.pathname.startsWith('/acciones/validar')?<CitizenActionValidationPage/>:location.pathname.startsWith('/admin')?<AdminPage/>:<PublicApp/>}
